"""Tests for the PRs tab startup cache."""

import json
import os
import time
from pathlib import Path

from personal_assistant_dashboard.prs_tab import PrsTab

REVIEW_PRS = [{"html_url": "u1", "title": "one", "labels": [{"name": "bug"}]}]
MY_PRS = [{"html_url": "u2", "title": "two", "labels": []}]


def _tab(tmp_path: Path) -> PrsTab:
    """PrsTab with only the attributes the cache methods touch."""
    tab = PrsTab.__new__(PrsTab)
    tab._state_path = tmp_path
    tab._loaded = []

    def _capture(*args):
        tab._loaded.append(args)

    tab._on_data_loaded = _capture  # type: ignore[method-assign]
    return tab


def _save(tab: PrsTab) -> None:
    tab._save_cache(
        REVIEW_PRS,
        MY_PRS,
        {"u1": (2, True)},
        {"u2"},
        {"u2": 1},
        {"u1"},
        {"u1": (10, 4), "u2": (0, 7)},
    )


def test_roundtrip(tmp_path: Path):
    tab = _tab(tmp_path)
    _save(tab)
    age_ms = tab._load_cache()
    assert age_ms is not None and age_ms >= 0
    review, my, meta, queued, incoming, requested, diffstat = tab._loaded[0]
    assert review == REVIEW_PRS
    assert my == MY_PRS
    assert meta == {"u1": (2, True)}
    assert queued == {"u2"}
    assert incoming == {"u2": 1}
    assert requested == {"u1"}
    assert diffstat == {"u1": (10, 4), "u2": (0, 7)}


def test_age_reflects_mtime(tmp_path: Path):
    tab = _tab(tmp_path)
    _save(tab)
    path = tmp_path / "prs_cache.json"
    old = time.time() - 600
    os.utime(path, (old, old))
    age_ms = tab._load_cache()
    assert age_ms is not None
    assert 595_000 < age_ms < 605_000


def test_future_mtime_clamps_to_zero(tmp_path: Path):
    tab = _tab(tmp_path)
    _save(tab)
    path = tmp_path / "prs_cache.json"
    future = time.time() + 600
    os.utime(path, (future, future))
    assert tab._load_cache() == 0


def test_missing_file(tmp_path: Path):
    assert _tab(tmp_path)._load_cache() is None


def test_corrupt_file(tmp_path: Path):
    (tmp_path / "prs_cache.json").write_text("{not json")
    tab = _tab(tmp_path)
    assert tab._load_cache() is None
    assert tab._loaded == []


def test_missing_key(tmp_path: Path):
    (tmp_path / "prs_cache.json").write_text(json.dumps({"review_prs": []}))
    tab = _tab(tmp_path)
    assert tab._load_cache() is None
    assert tab._loaded == []
